const key='word-roots-v1';let state={cards:{},logs:[],limit:10,excluded:[],...schedulerIdentity};let storageOK=true;try{const raw=localStorage.getItem(key);if(raw){const s=JSON.parse(raw);if(s.cards&&Array.isArray(s.logs)){state=migrateProgress(s);if(s.scheduler!=='fsrs-6'){if(!localStorage.getItem(key+'-before-fsrs'))localStorage.setItem(key+'-before-fsrs',raw);localStorage.setItem(key,JSON.stringify(state))}}}}catch{storageOK=false}try{state=applyRequestedTestReset(state,localStorage)}catch{storageOK=false}let view='home',queue=[],total=0,sessionWords=[],sessionNewTarget=state.limit,revealed=false,active=null,query='',family='',browse=false,selectedRoot=null;const app=document.getElementById('app');const day=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'});const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{storageOK=false;toast('儲存失敗，請匯出備份，避免進度遺失。')}}function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)}const isExcluded=word=>state.excluded.includes(word);function due(){
 // A forgotten word remains part of today's work even before its FSRS retry time.
 // Only the latest grade counts, so a later successful review resolves the retry.
 const latest=new Map(state.logs.map(log=>[log.word,log]));
 const today=day(),now=Date.now();
 return words.filter(w=>{
  if(isExcluded(w.word)||!state.cards[w.word])return false;
  const last=latest.get(w.word);
  const card=state.cards[w.word];
  const calendarDue=card.state===FSRS.State.Review&&card.scheduled_days>=1&&taipeiDate(new Date(card.due))<=today;
  return card.due<=now||calendarDue||(last?.day===today&&last.rating===1);
 }).sort((a,b)=>state.cards[a.word].due-state.cards[b.word].due);
}const fresh=()=>words.filter(w=>!isExcluded(w.word)&&!state.cards[w.word]);const learnedToday=()=>new Set(state.logs.filter(l=>l.day===day()&&l.first).map(l=>l.word)).size;
function learningStreak(now=new Date()){
 const days=new Set(state.logs.map(log=>log.day));
 const date=new Date(taipeiDate(now)+'T00:00:00Z');
 if(!days.has(taipeiDate(now)))date.setUTCDate(date.getUTCDate()-1);
 let streak=0;
 while(days.has(date.toISOString().slice(0,10))){streak++;date.setUTCDate(date.getUTCDate()-1)}
 return streak;
}
function learningTotals(){
 const total=words.length;
 const learned=words.filter(w=>Boolean(state.cards[w.word])).length;
 const days=new Set(state.logs.map(l=>l.day)).size;
 const percentage=total?Math.floor(learned/total*1000)/10:0;
 return {total,learned,days,percentage};
}
function estimatedNewWordDate(now=new Date()){
 const today=now.toLocaleDateString('sv-SE',{timeZone:'Asia/Taipei'});
 const remaining=fresh().length;
 const completedToday=new Set(state.logs.filter(l=>l.day===today&&l.first).map(l=>l.word)).size;
 const availableToday=Math.max(0,state.limit-completedToday);
 const extraDays=Math.ceil(Math.max(0,remaining-availableToday)/state.limit);
 // Add calendar days to the Taiwan date without relying on the device timezone.
 const finish=new Date(today+'T00:00:00Z');
 finish.setUTCDate(finish.getUTCDate()+extraDays);
 return finish.toISOString().slice(0,10).replaceAll('-','/');
}
let updateInProgress=false;
async function updateWebsite(){
 if(updateInProgress)return;
 updateInProgress=true;
 const button=document.getElementById('update-site');
 button.disabled=true;button.textContent='更新中…';button.setAttribute('aria-busy','true');
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
 try{
  // /index.html is outside the old worker's precache routes. This request also
  // works for installations whose current worker predates the update button.
  const url=new URL('index.html',document.baseURI);url.searchParams.set('app-update',Date.now());
  const response=await fetch(url.href,{cache:'no-store',signal:controller.signal});
  if(!response.ok||!response.headers.get('content-type')?.includes('text/html'))throw Error('Update unavailable');
  const html=await response.text();
  if(!html.includes('id="app"')||!html.includes('英文不散'))throw Error('Unexpected page');
  // Replace HTML only, including the cache held by a previously installed worker.
  // Never remove caches or change localStorage: learning records stay intact.
  if(globalThis.caches){
   const names=(await caches.keys()).filter(name=>name.startsWith('english-study-')||name.startsWith('word-roots-'));
   await Promise.all(names.map(async name=>{const cache=await caches.open(name);await cache.put(new URL('./',document.baseURI).href,new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8'}}))}));
  }
  location.reload();
 }catch{
  toast('更新失敗，請確認網路連線後再試一次。');
 }finally{
  clearTimeout(timeout);updateInProgress=false;
  button.disabled=false;button.textContent='更新';button.removeAttribute('aria-busy');
 }
}
function learningSummaryMarkup(){
 const {total,learned,days,percentage}=learningTotals();
 const percentLabel=learned&&percentage===0?'&lt;0.1':percentage;
 return `<section class="panel learning-summary" aria-label="學習累積"><div class="learning-days"><span>累計學習</span><div><b>${days}</b><span>天</span></div></div><div class="learning-completion"><div class="row"><strong>總學習進度</strong><span class="learning-percentage">${percentLabel}%</span></div><progress value="${learned}" max="${total||1}" aria-label="總學習進度" aria-valuetext="已學習 ${learned} 個，共 ${total} 個單字"></progress><p class="note">預計學完新字：${estimatedNewWordDate()}</p></div></section>`;
}
