function results(){const list=words.filter(w=>(!family||components(w).some(c=>c[0]===family))&&(`${w.word} ${w.zh}`.toLowerCase().includes(query.toLowerCase())));document.getElementById('results').innerHTML=`<p class="note">${list.length} 個單字</p>`+list.map(w=>`<div class="list-item"><button data-word="${w.word}"><span class="library-word-heading"><strong>${esc(w.word)}</strong>${isExcluded(w.word)?'<span class="excluded-label">(不再出現)</span>':''}</span>${kkMarkup(w)}<span>${esc(w.zh)}</span></button>${rootBadgeMarkup(w)}</div>`).join('');document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{active=words.find(w=>w.word===b.dataset.word);browse=true;revealed=true;selectedRoot=null;view='study';render();scrollStudyTop();playPronunciation(active.word)})}
function fillTodayQueue(){
 const queued=new Set(queue.map(w=>w.word));
 const reviews=due().filter(w=>!queued.has(w.word));
 const pendingNew=queue.filter(w=>!state.cards[w.word]).length;
 const slots=Math.max(0,sessionNewTarget-learnedToday()-pendingNew);
 const newWords=fresh().filter(w=>!queued.has(w.word)).slice(0,slots);
 const additions=[...reviews,...newWords];
 queue.push(...additions);total+=additions.length;
}
function start(extend=false){browse=false;queue=[];total=0;sessionWords=[];sessionNewTarget=extend?learnedToday()+state.limit:state.limit;view='study';next()}
function next(){
 const before=queue.length;
 queue=queue.filter(w=>!isExcluded(w.word));
 total-=before-queue.length;
 // Reconcile remaining daily work after every answer or exclusion, before
 // deciding the session is finished. Queued new words reserve their slots.
 fillTodayQueue();
 active=queue.shift();if(active&&!sessionWords.some(w=>w.word===active.word))sessionWords.push(active);revealed=false;selectedRoot=null;render();scrollStudyTop();
 if(active)playPronunciation(active.word);
}
function sessionSummaryMarkup(){
 if(!sessionWords.length)return '';
 return `<section class="session-summary" aria-label="本輪學習單字"><h2>本輪單字</h2><div class="session-word-list">${sessionWords.map(w=>`<div class="list-item"><span><span class="library-word-heading"><strong>${esc(w.word)}</strong>${isExcluded(w.word)?'<span class="excluded-label">(不再出現)</span>':''}</span>${kkMarkup(w)}<span>${esc(w.zh)}</span></span></div>`).join('')}</div></section>`;
}
function renderCard(){if(!active){stopPronunciation();app.innerHTML=`<div class="study panel"><h1>這輪完成了。</h1><p>本輪練習了 ${sessionWords.length} 個單字。</p>${sessionSummaryMarkup()}<button class="primary" id="back">返回今日</button></div>`;document.getElementById('back').onclick=()=>{view='home';render()};return}const w=active;const c=state.cards[w.word];const intervals=getIntervals(c);app.innerHTML=`<div class="study"><div class="row"><button id="back">${browse?'返回字庫':'結束這輪'}</button><span class="note">${browse?'字庫預覽':`${total-queue.length} / ${total}`}</span></div>${browse&&isExcluded(w.word)?'<div class="excluded-status"><span>已設為不再出現</span><button id="restore-word">恢復學習</button></div>':''}${browse?'':`<progress value="${total-queue.length-1}" max="${total}"></progress>`}<div class="panel">${rootBadgeMarkup(w)}<div class="word-row"><div class="word">${w.word}</div><button id="speak" aria-label="播放單字發音"><svg aria-hidden="true" focusable="false" viewBox="0 0 24 24"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg></button></div>${kkMarkup(w)}${revealed?`<p class="muted">${esc(w.pos)}</p>`:'<div class="card-question"><p class="muted">先想想：這個字是什麼意思？</p>'}${revealed?`<div class="answer"><div class="meaning">${esc(w.zh)}</div>${rootMarkup(w)}${w.word==='generation'||w.word==='generous'?'<p>generation = 世代；generous = 慷慨的。意思分開記，別只靠開頭 gen 判斷。</p>':''}${examples[w.word]?`<p>${esc(examples[w.word][0])}<br><span class="muted">${esc(examples[w.word][1])}</span></p>`:''}</div>`:`<button class="primary full" id="reveal">${components(w).length?'查看意思與字根':'查看意思'}</button></div>`}</div>${revealed&&!browse?`<div class="ratings">${['忘記','困難','記得','簡單'].map((s,i)=>`<button class="${['again','','good','easy'][i]}" data-rate="${i+1}">${s}<small>${i===0?'本輪再練':label(intervals[i])}</small></button>`).join('')}<button id="exclude-word" class="exclude">不再出現</button></div>`:''}</div>`;document.getElementById('back').onclick=()=>{view=browse?'library':'home';render()};document.getElementById('speak').onclick=()=>playPronunciation(w.word,true);const excludeButton=document.getElementById('exclude-word');if(excludeButton)excludeButton.onclick=excludeActiveWord;const restoreButton=document.getElementById('restore-word');if(restoreButton)restoreButton.onclick=()=>{state.excluded=state.excluded.filter(word=>word!==w.word);save();render();toast('已恢復學習')};if(!revealed)document.getElementById('reveal').onclick=()=>{revealed=true;render()};document.querySelectorAll('[data-root]').forEach(b=>b.onclick=()=>{selectedRoot=b.dataset.root===selectedRoot?null:b.dataset.root;render()});document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rate(Number(b.dataset.rate)))}
function scrollStudyTop(){try{globalThis.scrollTo?.({top:0,behavior:'auto'})}catch{}}
function stopPronunciation(){
 try{globalThis.speechSynthesis?.cancel()}catch{}
}
function playPronunciation(word,manual=false){
 const synth=globalThis.speechSynthesis,Utterance=globalThis.SpeechSynthesisUtterance;
 if(!synth||!Utterance){if(manual)toast('這個瀏覽器不支援發音。');return}
 try{
  // Replacing the previous utterance prevents rapid answers from queuing audio.
  synth.cancel();
  const utterance=new Utterance(word);
  utterance.lang='en-US';utterance.rate=.85;
  synth.speak(utterance);
 }catch{if(manual)toast('無法播放發音，請再試一次。')}
}
function excludeActiveWord(){if(!active||browse)return;const word=active.word;if(!isExcluded(word))state.excluded.push(word);save();next();toast('此字不再出現；可到字庫恢復學習')}
function getIntervals(c){return schedulePreview(c)}
function label(n){if(n===30)return '1 個月';if(n<1/24)return `${Math.max(1,Math.round(n*1440))} 分鐘`;if(n<1)return `${Math.round(n*24)} 小時`;return `${Math.round(n)} 天`}
function rate(r){
 if(![1,2,3,4].includes(r)||!active)return;
 const first=!state.cards[active.word];const now=new Date();
 const result=scheduleReview(state.cards[active.word],r,now);
 state.cards[active.word]=result.card;
 state.logs.push({word:active.word,rating:r,day:day(),first,review:now.getTime(),fsrs:result.log});
 // Append immediately: the session must not wait for the FSRS due timestamp.
 if(r===1&&!queue.some(w=>w.word===active.word)){
  queue.push(active);
  total++;
 }
 save();next();
}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render()});render();if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('sw.js',document.baseURI)).catch(()=>{});

function kkMarkup(w){
 const readings=kkVariants[w.word]||[['',w.kk||kkPronunciations[w.word]]];
 return `<span class="kk-pronunciation" aria-label="美式 KK 音標">KK ${readings.map(([pos,kk])=>`<span class="kk-reading">${pos?esc(pos)+' ':''}[${esc(kk)}]</span>`).join(' · ')}</span>`;
}
function rootBadgeMarkup(w){
 const roots=components(w).filter(c=>rootInfo[c[0]].kind==='字根');
 return roots.length?`<span class="chip">${roots.map(c=>esc(rootInfo[c[0]].label)).join(' · ')}</span>`:'';
}
function rootMarkup(w){
 const parts=components(w);
 if(!parts.length)return '';
 const split=parts.map(c=>c[2]||rootInfo[c[0]].label).join(' ＋ ');
 let html=`<div class="parts"><strong>${esc(split)}</strong>${decompositionNotes[w.word]?`<p>${esc(decompositionNotes[w.word])}</p>`:''}</div><div class="root-buttons">`+parts.map(([id,meaning,variant])=>`<button data-root="${esc(id)}" aria-expanded="${selectedRoot===id}" class="root-button ${selectedRoot===id?'chosen':''}"><strong>${esc(variant||rootInfo[id].label)}</strong><span>${esc(meaning||rootInfo[id].meaning)}</span>${variant?`<small>${esc(rootInfo[id].label)} 的變形</small>`:''}</button>`).join('')+'</div>';
 if(selectedRoot&&parts.some(c=>c[0]===selectedRoot)){
  const r=rootInfo[selectedRoot],part=parts.find(c=>c[0]===selectedRoot),all=rootMatches(selectedRoot,w.word),list=all.slice(0,10);
  html+=`<section class="root-detail" aria-label="相關單字"><h2>${esc(part[2]||r.label)}</h2><p>${esc(part[1]||r.meaning)}</p>${list.map(x=>`<div class="list-item"><span><strong>${esc(x.word)}</strong>${kkMarkup(x)}<span>${esc(x.zh)}</span></span></div>`).join('')||'<p class="muted">目前字庫尚無其他相關字。</p>'}<p class="note"><a href="${esc(r.source)}" target="_blank" rel="noopener">${r.source.startsWith('https://membean.com/')?'Membean 詞素目錄':'Etymonline 詞素核對'}</a></p></section>`;
 }
 const sources=[...(parts.some(c=>rootInfo[c[0]].source.startsWith('https://membean.com/'))?[rootSource]:[]),...(decompositionSources[w.word]||[])];
 html+=`<p class="note root-source">${sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join(' · ')}</p>`;
 return html;
}

setInterval(()=>{if(view==='home'&&document.querySelector('.daily-quote')?.dataset.date!==taipeiDate())render()},60000);
